def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(grid[0]) if v != 0 and any(all(x == v for x in row) for row in grid))
    hr = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    vc = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]
    ph, pw = hr[0], vc[0]
    nr, nc = len(hr)+1, len(vc)+1
    motif=[]
    for di in range(ph):
        for dj in range(pw):
            if grid[ph+di][2*pw+dj] not in (0,sep): motif.append((di,dj))
    colors=[]
    for r in range(nr):
        vals=[grid[r*(ph+1)+i][j] for i in range(ph) for j in range(pw) if grid[r*(ph+1)+i][j] not in (0,sep)]
        colors.append(vals[0] if vals else 0)
    out=[row[:] for row in grid]
    for r in range(nr):
        for c in range(nc):
            for di in range(ph):
                for dj in range(pw): out[r*(ph+1)+di][c*(pw+1)+dj]=0
    for r in range(nr):
        for c in range(nc):
            for di,dj in motif: out[r*(ph+1)+di][c*(pw+1)+dj]=colors[r]
    return out
